begin
  select post_id into pid from public.blog_post_translations where locale = 'en' and slug = $v$architect-vs-interior-architect-vs-interior-designer$v$;
  if pid is null then
    insert into public.blog_posts (status) values ('draft') returning id into pid;
  end if;
  update public.blog_posts set
    status = 'published', publish_at = coalesce(publish_at, now()),
    category_id = (select id from public.blog_categories where slug = $v$interior-design$v$),
    author_id = (select id from public.blog_authors where slug = 'vari-studio'),
    cover = $v$b80319_962a6cc04617409f94ea031705d4ee66~mv2.png$v$,
    cover_alt = $v${"en": "Vaulted timber living room with a stone fireplace in Hearthstone Haven, Telemark, Norway", "de": "Gewölbtes Wohnzimmer aus Holz mit Steinkamin in Hearthstone Haven, Telemark, Norwegen", "es": "Salón abovedado de madera con chimenea de piedra en Hearthstone Haven, Telemark, Noruega", "tr": "Hearthstone Haven'da taş şömineli, tonozlu ahşap oturma odası, Telemark, Norveç"}$v$::jsonb,
    faq = $v$[{"q": {"en": "Can an interior designer remove walls?", "de": "Darf ein Interior Designer Wände entfernen?", "es": "¿Puede un diseñador de interiores quitar tabiques?", "tr": "Bir iç tasarımcı duvar kaldırabilir mi?"}, "a": {"en": "Not on their own if the wall is load-bearing or the change needs approval. That requires an architect or interior architect and a structural engineer, and often a permit. Non-structural partitions are a different matter, but check local rules.", "de": "Nicht allein, wenn die Wand tragend ist oder die Änderung genehmigungspflichtig ist. Dafür braucht es einen Architekten oder Innenarchitekten und einen Tragwerksplaner, oft auch eine Genehmigung. Nichttragende Trennwände sind etwas anderes, prüfen Sie aber die Regeln vor Ort.", "es": "No por sí solo si el muro es de carga o el cambio necesita licencia. Eso requiere un arquitecto o interiorista técnico y un ingeniero de estructuras, y a menudo un permiso. Los tabiques no estructurales son otra cosa, pero consulte las normas locales.", "tr": "Duvar taşıyıcıysa ya da değişiklik izin gerektiriyorsa tek başına kaldıramaz. Bunun için bir mimar ya da iç mimar ile bir inşaat mühendisi, çoğu zaman da izin gerekir. Taşıyıcı olmayan bölmeler başka bir konudur, ama yerel kuralları kontrol edin."}}, {"q": {"en": "Is an interior architect a real architect?", "de": "Ist ein Innenarchitekt ein richtiger Architekt?", "es": "¿Un arquitecto de interiores es un arquitecto de verdad?", "tr": "İç mimar gerçek bir mimar mıdır?"}, "a": {"en": "In some countries, such as Germany, \"Innenarchitekt\" is a protected title with its own registration. Elsewhere the term is used more loosely. Check the person's registration where your project is.", "de": "In manchen Ländern, etwa in Deutschland, ist „Innenarchitekt“ eine geschützte Bezeichnung mit eigener Kammereintragung. Anderswo wird der Begriff lockerer verwendet. Prüfen Sie die Eintragung der Person dort, wo Ihr Projekt liegt.", "es": "En algunos países, como Alemania, «Innenarchitekt» es un título protegido con su propia inscripción. En otros el término se usa con más libertad. Compruebe la colegiación de la persona en el lugar de su proyecto.", "tr": "Almanya gibi bazı ülkelerde \"Innenarchitekt\" kendi kaydı olan korunmuş bir unvandır. Başka yerlerde terim daha serbest kullanılır. Projenizin bulunduğu yerde kişinin kaydını kontrol edin."}}, {"q": {"en": "Who is cheaper, an architect or an interior designer?", "de": "Wer ist günstiger, Architekt oder Interior Designer?", "es": "¿Quién es más barato, un arquitecto o un diseñador de interiores?", "tr": "Hangisi daha ucuz, mimar mı iç tasarımcı mı?"}, "a": {"en": "It depends on scope. For a refresh, an interior designer is usually more economical. For structural work or a new building you need an architect regardless, and a good one saves money by avoiding costly mistakes.", "de": "Das hängt vom Umfang ab. Für eine Auffrischung ist ein Interior Designer meist wirtschaftlicher. Für Eingriffe ins Tragwerk oder einen Neubau brauchen Sie ohnehin einen Architekten, und ein guter spart Geld, weil er teure Fehler vermeidet.", "es": "Depende del alcance. Para una renovación, un diseñador de interiores suele ser más económico. Para cambios estructurales o una obra nueva necesitará un arquitecto de todos modos, y uno bueno ahorra dinero evitando errores caros.", "tr": "Kapsama bağlıdır. Bir yenileme için iç tasarımcı genellikle daha ekonomiktir. Taşıyıcı değişiklik ya da yeni bina için zaten bir mimara ihtiyacınız var; iyi bir mimar pahalı hataları önleyerek para kazandırır."}}, {"q": {"en": "Do I need both an architect and an interior designer?", "de": "Brauche ich Architekt und Interior Designer?", "es": "¿Necesito un arquitecto y un diseñador de interiores?", "tr": "Hem mimara hem iç tasarımcıya ihtiyacım var mı?"}, "a": {"en": "For new buildings and major renovations, often yes. The architect handles the building and approvals, the interior designer the spaces people live and work in. The best results come when they collaborate from the start.", "de": "Bei Neubauten und großen Sanierungen oft ja. Der Architekt kümmert sich um Gebäude und Genehmigungen, der Interior Designer um die Räume, in denen Menschen leben und arbeiten. Die besten Ergebnisse entstehen, wenn beide von Anfang an zusammenarbeiten.", "es": "En obra nueva y grandes reformas, a menudo sí. El arquitecto se ocupa del edificio y las licencias; el diseñador de interiores, de los espacios donde se vive y se trabaja. Los mejores resultados llegan cuando colaboran desde el principio.", "tr": "Yeni binalarda ve büyük renovasyonlarda çoğu zaman evet. Mimar bina ve izinlerle, iç tasarımcı insanların yaşadığı ve çalıştığı mekânlarla ilgilenir. En iyi sonuçlar baştan birlikte çalıştıklarında çıkar."}}]$v$::jsonb
  where id = pid;
  insert into public.blog_post_translations (post_id, locale, slug, title, excerpt, html, takeaways, seo_title, seo_description, focus_keyword, ready, word_count)
  values
  (pid, $v$en$v$, $v$architect-vs-interior-architect-vs-interior-designer$v$, $v$Architect, Interior Architect or Interior Designer: Who Do You Need?$v$, $v$Who does what, where the legal lines are, how fees usually work, and which professional your project needs: a clear guide for homeowners and businesses.$v$, $v$<p>The three titles overlap enough to confuse almost everyone, including people who hire them regularly. The short version: an <strong>architect</strong> designs buildings and is responsible for their structure, safety and approval. An <strong>interior designer</strong> shapes the inside of spaces: layout, finishes, furniture, light and atmosphere. An <strong>interior architect</strong> sits between the two, working on interiors with a deeper reach into construction, such as moving walls, new stairs and building services.</p>
<p>Which one you need depends on one question: <strong>what is your project going to change?</strong></p>
<h2>Start with what changes</h2>
<p><strong>A new building or an extension.</strong> You need an architect. New structures require design that meets building regulations, structural coordination and, in most places, a permit application signed by a qualified professional.</p>
<p><strong>Structural changes inside an existing building.</strong> Removing a load-bearing wall, adding a mezzanine, changing a staircase or rerouting services means an architect or an interior architect, plus a structural engineer. Many jurisdictions require approval for this kind of work.</p>
<p><strong>A fit-out within an existing shell.</strong> A new apartment or office being finished inside a completed building is the natural territory of interior architects and interior designers: layout, kitchens, bathrooms, joinery, lighting, finishes.</p>
<p><strong>A refresh.</strong> New finishes, furniture, colour and lighting without touching the structure. An interior designer is usually the right choice.</p>
<p>Many projects need more than one of these. A villa needs an architect for the building and an interior designer for the rooms, and the result is better when they talk early.</p>
<figure data-figure="" data-size="normal"><img src="https://static.wixstatic.com/media/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png/v1/fit/w_1800,h_3600,q_82,enc_avif,quality_auto/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png" alt="Timeless English Roof Architecture: architectural visualization by VARI Studio" loading="lazy"></figure>
<h2>Architect vs interior designer: what each one actually does</h2>
<p><strong>Architects</strong> take a project from brief and site through concept, design development and technical drawings to permits and, often, supervision on site. They coordinate engineers and are accountable for compliance with building regulations.</p>
<p><strong>Interior architects</strong> design interior spaces as constructed environments: spatial planning, partitions, ceilings, stairs, lighting and services coordination, with technical drawings that contractors build from.</p>
<p><strong>Interior designers</strong> focus on how a space looks, feels and works for the people in it: layout, materials, colour, furniture, textiles, lighting and styling. Many also manage purchasing and installation.</p>
<h2>The legal lines differ by country</h2>
<p>Professional titles are regulated differently around the world, so check the rules where your project is:</p>
<ul><li><strong>Germany.</strong> "Architekt" and "Innenarchitekt" are protected professional titles under the architects' laws of the federal states. Only people registered with a state chamber of architects (Architektenkammer) may use them.</li><li><strong>United Kingdom.</strong> The title "architect" is protected by law. Only people registered with the Architects Registration Board may use it.</li><li><strong>United States.</strong> Architects are licensed by each state. Interior design regulation varies widely: some states regulate the title or the practice, many do not.</li></ul>
<p>Elsewhere, ask your local professional body or the authority that issues building permits who may design and sign the kind of work you plan.</p>
<h2>How fees usually work</h2>
<p>Architects often quote a percentage of construction cost, a fixed fee per stage, or hourly rates. In Germany, the official fee regulation for architects and engineers (HOAI) is a common reference. Since 2021 its rates have been guidance rather than binding minimums. Interior architects and designers typically charge fixed fees per project or per room, hourly rates, a fee per square metre, or a combination. Some add a margin on furniture they purchase for you.</p>
<p>Whichever model you choose, ask for the scope in writing: which stages are included, how many design options, how many revisions, and whether site visits and purchasing are part of it.</p>
<h2>Seeing the result before you decide</h2>
<p>Whoever designs your project, decisions are easier when you can see them. 3D visualization lets you compare layouts, materials and lighting before anything is ordered or built. That works for a single room as well as for a whole building. Our <a href="/en/blog/interior-rendering-guide">interior rendering guide</a> explains how that process works and how to brief it.</p>
<h2>When one studio can cover several roles</h2>
<p>Hiring separate firms for the building, the interiors and the images means three handovers. Some studios combine design and visualization, so the same team develops a concept and shows it. At VARI we work across architectural design, interior design and 3D visualization, from 2D drafting and BIM to renders and virtual tours. You can see examples in <a href="/en/work">our projects</a>, such as the vaulted living room of <a href="/en/work/hearthstone-haven">Hearthstone Haven</a>, or read about our <a href="/en/services">services</a>.</p>
<p>Not sure what your project needs? <a href="/en/contact">Describe it to us</a> and we will tell you honestly, including when you need a locally registered architect.</p>
<h2>References</h2>
<ul><li>Bundesarchitektenkammer (German Federal Chamber of Architects), on protected titles: <a href="https://bak.de">bak.de</a></li><li>Architects Registration Board (UK): <a href="https://arb.org">arb.org</a>.uk</li><li>HOAI, Honorarordnung für Architekten und Ingenieure (2021 version): <a href="https://gesetze-im-internet.de/hoai_2013">gesetze-im-internet.de/hoai_2013</a></li></ul>$v$, $v$["Architects design buildings and are accountable for structure, safety and approvals.", "Interior architects work on interiors with a reach into construction; interior designers shape layout, finishes and atmosphere.", "What your project changes decides who you need: new building, structural change, fit-out or refresh.", "Professional titles are protected differently by country; check local rules."]$v$::jsonb, $v$Architect vs Interior Architect vs Interior Designer$v$, $v$Architect vs interior designer vs interior architect: who does what, where the legal lines are, how fees work and which one your project needs.$v$, $v$architect vs interior designer$v$, true, 763),
  (pid, $v$de$v$, $v$architekt-innenarchitekt-interior-designer$v$, $v$Architekt, Innenarchitekt oder Interior Designer: Wen brauchen Sie?$v$, $v$Wer was macht, wo die rechtlichen Grenzen liegen, wie Honorare meist funktionieren und welche Fachleute Ihr Projekt braucht: ein klarer Leitfaden für Eigentümer und Unternehmen.$v$, $v$<p>Architekt, Innenarchitekt, Interior Designer: Die drei Berufsbezeichnungen überschneiden sich so stark, dass fast alle sie verwechseln, auch Menschen, die sie regelmäßig beauftragen. Die Kurzfassung: Ein <strong>Architekt</strong> entwirft Gebäude und ist für Tragwerk, Sicherheit und Genehmigung verantwortlich. Ein <strong>Interior Designer</strong> gestaltet das Innere von Räumen: Aufteilung, Oberflächen, Möbel, Licht und Atmosphäre. Ein <strong>Innenarchitekt</strong> steht dazwischen und arbeitet an Innenräumen mit tieferem Eingriff in die Konstruktion, etwa versetzte Wände, neue Treppen und Haustechnik.</p>
<p>Wen Sie brauchen, hängt von einer Frage ab: <strong>Was wird Ihr Projekt verändern?</strong></p>
<h2>Beginnen Sie bei dem, was sich ändert</h2>
<p><strong>Ein Neubau oder ein Anbau.</strong> Sie brauchen einen Architekten. Neue Bauwerke erfordern einen Entwurf, der dem Baurecht entspricht, eine Abstimmung mit der Tragwerksplanung und in den meisten Ländern einen Bauantrag, den eine berechtigte Fachperson unterschreibt.</p>
<p><strong>Eingriffe ins Tragwerk eines bestehenden Gebäudes.</strong> Eine tragende Wand entfernen, eine Galerie einziehen, eine Treppe ändern oder Leitungen neu führen: Dafür brauchen Sie einen Architekten oder Innenarchitekten sowie einen Tragwerksplaner. Vielerorts ist dafür eine Genehmigung nötig.</p>
<p><strong>Ein Ausbau im bestehenden Rohbau.</strong> Eine neue Wohnung oder ein Büro, das in einem fertigen Gebäude ausgebaut wird, ist das natürliche Feld von Innenarchitekten und Interior Designern: Grundriss, Küchen, Bäder, Einbauten, Licht, Oberflächen.</p>
<p><strong>Eine Auffrischung.</strong> Neue Oberflächen, Möbel, Farben und Licht ohne Eingriff ins Tragwerk. Meist ist ein Interior Designer die richtige Wahl.</p>
<p>Viele Projekte brauchen mehr als eine dieser Rollen. Eine Villa braucht einen Architekten für das Gebäude und einen Interior Designer für die Räume, und das Ergebnis wird besser, wenn beide früh miteinander sprechen.</p>
<figure data-figure="" data-size="normal"><img src="https://static.wixstatic.com/media/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png/v1/fit/w_1800,h_3600,q_82,enc_avif,quality_auto/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png" alt="Timeless English Roof Architecture: Architekturvisualisierung von VARI Studio" loading="lazy"></figure>
<h2>Architekt, Innenarchitekt, Interior Designer: was jeder tatsächlich macht</h2>
<p><strong>Architekten</strong> führen ein Projekt von Aufgabe und Grundstück über Konzept, Entwurf und Ausführungsplanung bis zur Genehmigung und oft bis zur Bauüberwachung. Sie koordinieren die Fachplaner und verantworten die Einhaltung des Baurechts.</p>
<p><strong>Innenarchitekten</strong> planen Innenräume als gebaute Umgebung: Raumplanung, Trennwände, Decken, Treppen, Licht und die Abstimmung der Haustechnik, mit Ausführungsplänen, nach denen die Firmen bauen.</p>
<p><strong>Interior Designer</strong> konzentrieren sich darauf, wie ein Raum für die Menschen darin aussieht, wirkt und funktioniert: Aufteilung, Materialien, Farbe, Möbel, Textilien, Licht und Ausstattung. Viele übernehmen auch Einkauf und Montage.</p>
<h2>Die rechtlichen Grenzen sind von Land zu Land verschieden</h2>
<p>Berufsbezeichnungen sind weltweit unterschiedlich geregelt. Prüfen Sie daher die Regeln dort, wo Ihr Projekt liegt:</p>
<ul><li><strong>Deutschland.</strong> „Architekt“ und „Innenarchitekt“ sind nach den Architektengesetzen der Länder geschützte Berufsbezeichnungen. Nur wer in die Liste einer Architektenkammer eingetragen ist, darf sie führen.</li><li><strong>Großbritannien.</strong> Die Bezeichnung „architect“ ist gesetzlich geschützt. Nur wer beim Architects Registration Board eingetragen ist, darf sie führen.</li><li><strong>USA.</strong> Architekten werden von jedem Bundesstaat zugelassen. Die Regeln für Interior Design sind sehr unterschiedlich: Manche Staaten regeln die Bezeichnung oder die Tätigkeit, viele nicht.</li></ul>
<p>Fragen Sie andernorts die zuständige Berufskammer oder die Baugenehmigungsbehörde, wer die geplante Arbeit entwerfen und unterschreiben darf.</p>
<h2>Wie Honorare meist funktionieren</h2>
<p>Architekten rechnen oft mit einem Prozentsatz der Baukosten, einem Pauschalhonorar je Leistungsphase oder nach Stunden ab. In Deutschland ist die Honorarordnung für Architekten und Ingenieure (HOAI) ein verbreiteter Bezugspunkt. Seit 2021 sind ihre Sätze eine Orientierung und keine verbindlichen Mindestsätze mehr. Innenarchitekten und Interior Designer berechnen meist Pauschalen pro Projekt oder Raum, Stundensätze, ein Honorar pro Quadratmeter oder eine Kombination. Manche schlagen auf Möbel, die sie für Sie einkaufen, eine Marge auf.</p>
<p>Welches Modell Sie auch wählen: Lassen Sie sich den Leistungsumfang schriftlich geben. Welche Phasen sind enthalten, wie viele Entwurfsvarianten, wie viele Korrekturen, und gehören Baustellenbesuche und Einkauf dazu?</p>
<h2>Das Ergebnis sehen, bevor Sie entscheiden</h2>
<p>Wer auch immer Ihr Projekt entwirft: Entscheidungen fallen leichter, wenn man sie sehen kann. Mit 3D-Visualisierung vergleichen Sie Grundrisse, Materialien und Licht, bevor etwas bestellt oder gebaut wird. Das gilt für einen einzelnen Raum genauso wie für ein ganzes Gebäude. Unser <a href="/de/blog/innenraumvisualisierung-ratgeber">Ratgeber zur Innenraumvisualisierung</a> erklärt, wie dieser Ablauf funktioniert und wie Sie ihn briefen. Welche Entscheidungen Bilder konkret erleichtern, lesen Sie in <a href="/de/blog/3d-visualisierung-interior-design">3D-Visualisierung im Interior Design</a>.</p>
<h2>Wenn ein Studio mehrere Rollen abdeckt</h2>
<p>Getrennte Firmen für Gebäude, Innenräume und Bilder bedeuten drei Übergaben. Manche Studios verbinden Entwurf und Visualisierung, sodass dasselbe Team ein Konzept entwickelt und zeigt. Bei VARI arbeiten wir in Architekturentwurf, Interior Design und 3D-Visualisierung, von 2D-Zeichnung und BIM bis zu Renderings und virtuellen Rundgängen. Beispiele finden Sie in <a href="/de/work">unseren Projekten</a>, etwa das gewölbte Wohnzimmer von <a href="/de/work/hearthstone-haven">Hearthstone Haven</a>, oder unter <a href="/de/services">Leistungen</a>.</p>
<p>Nicht sicher, was Ihr Projekt braucht? <a href="/de/contact">Beschreiben Sie es uns</a>, und wir sagen es Ihnen ehrlich, auch wenn Sie einen vor Ort eingetragenen Architekten brauchen.</p>
<h2>Quellen</h2>
<ul><li>Bundesarchitektenkammer, zu geschützten Berufsbezeichnungen: <a href="https://bak.de">bak.de</a></li><li>Architects Registration Board (Großbritannien): <a href="https://arb.org">arb.org</a>.uk</li><li>HOAI, Honorarordnung für Architekten und Ingenieure (Fassung 2021): <a href="https://gesetze-im-internet.de/hoai_2013">gesetze-im-internet.de/hoai_2013</a></li></ul>$v$, $v$["Architekten entwerfen Gebäude und verantworten Tragwerk, Sicherheit und Genehmigung.", "Innenarchitekten arbeiten an Innenräumen bis in die Konstruktion; Interior Designer gestalten Raumaufteilung, Oberflächen und Atmosphäre.", "Was Ihr Projekt verändert, entscheidet, wen Sie brauchen: Neubau, Umbau am Tragwerk, Ausbau oder Auffrischung.", "Berufsbezeichnungen sind je nach Land unterschiedlich geschützt; prüfen Sie die Regeln vor Ort."]$v$::jsonb, $v$Architekt, Innenarchitekt oder Interior Designer?$v$, $v$Architekt, Innenarchitekt oder Interior Designer: wer was macht, wo die rechtlichen Grenzen liegen, wie Honorare funktionieren und wen Ihr Projekt braucht.$v$, $v$architekt innenarchitekt interior designer$v$, true, 741),
  (pid, $v$es$v$, $v$arquitecto-interiorista-o-disenador-de-interiores$v$, $v$Arquitecto, interiorista o diseñador de interiores: ¿a quién necesita?$v$, $v$Quién hace qué, dónde están los límites legales, cómo suelen funcionar los honorarios y qué profesional necesita su proyecto: una guía clara para propietarios y empresas.$v$, $v$<p>Arquitecto, interiorista o diseñador de interiores: los tres títulos se solapan tanto que confunden a casi todo el mundo, incluso a quien los contrata a menudo. La versión corta: un <strong>arquitecto</strong> diseña edificios y responde de su estructura, seguridad y licencia. Un <strong>diseñador de interiores</strong> da forma al interior de los espacios: distribución, acabados, muebles, luz y ambiente. Un <strong>interiorista</strong> con perfil técnico, lo que en otros países se llama arquitecto de interiores, está entre ambos: trabaja en interiores con más alcance en la construcción, como mover tabiques, nuevas escaleras e instalaciones.</p>
<p>A quién necesita depende de una pregunta: <strong>¿qué va a cambiar su proyecto?</strong></p>
<h2>Empiece por lo que cambia</h2>
<p><strong>Un edificio nuevo o una ampliación.</strong> Necesita un arquitecto. Las estructuras nuevas requieren un diseño que cumpla la normativa, coordinación estructural y, en casi todas partes, una solicitud de licencia firmada por un profesional habilitado.</p>
<p><strong>Cambios estructurales en un edificio existente.</strong> Quitar un muro de carga, añadir un altillo, cambiar una escalera o redistribuir instalaciones exige un arquitecto o un interiorista técnico, además de un ingeniero de estructuras. En muchos lugares este trabajo necesita licencia.</p>
<p><strong>Un acondicionamiento dentro de un edificio terminado.</strong> Un piso u oficina que se termina dentro de un edificio ya construido es el terreno natural de interioristas y diseñadores de interiores: distribución, cocinas, baños, carpintería, iluminación y acabados.</p>
<p><strong>Una renovación.</strong> Nuevos acabados, muebles, color e iluminación sin tocar la estructura. Normalmente, un diseñador de interiores es la opción adecuada.</p>
<p>Muchos proyectos necesitan más de un perfil. Una villa necesita un arquitecto para el edificio y un diseñador de interiores para las estancias, y el resultado mejora cuando hablan pronto.</p>
<figure data-figure="" data-size="normal"><img src="https://static.wixstatic.com/media/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png/v1/fit/w_1800,h_3600,q_82,enc_avif,quality_auto/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png" alt="Timeless English Roof Architecture: visualización arquitectónica de VARI Studio" loading="lazy"></figure>
<h2>Arquitecto, interiorista o diseñador de interiores: qué hace cada uno</h2>
<p><strong>Los arquitectos</strong> llevan un proyecto desde el encargo y el solar, pasando por el concepto, el desarrollo y los planos técnicos, hasta la licencia y, a menudo, la dirección de obra. Coordinan a los ingenieros y responden del cumplimiento normativo.</p>
<p><strong>Los interioristas técnicos</strong> diseñan los interiores como entornos construidos: planificación espacial, tabiquería, techos, escaleras, iluminación y coordinación de instalaciones, con planos técnicos con los que construyen los contratistas.</p>
<p><strong>Los diseñadores de interiores</strong> se centran en cómo se ve, se siente y funciona un espacio para quienes lo usan: distribución, materiales, color, muebles, textiles, iluminación y estilismo. Muchos gestionan también compras e instalación.</p>
<h2>Los límites legales cambian según el país</h2>
<p>Los títulos profesionales se regulan de forma distinta en cada país, así que consulte las normas del lugar de su proyecto:</p>
<ul><li><strong>Alemania.</strong> «Architekt» e «Innenarchitekt» son títulos protegidos por las leyes de arquitectos de los estados federados. Solo pueden usarlos quienes están inscritos en una cámara de arquitectos (Architektenkammer).</li><li><strong>Reino Unido.</strong> El título «architect» está protegido por ley. Solo pueden usarlo quienes están inscritos en el Architects Registration Board.</li><li><strong>Estados Unidos.</strong> Cada estado otorga la licencia de arquitecto. La regulación del diseño de interiores varía mucho: algunos estados regulan el título o la actividad, muchos no.</li></ul>
<p>En otros lugares, pregunte al colegio profesional o a la administración que concede las licencias quién puede diseñar y firmar el trabajo que planea.</p>
<h2>Cómo suelen cobrarse los honorarios</h2>
<p>Los arquitectos suelen presupuestar un porcentaje del coste de obra, un importe fijo por fase o tarifas por hora. En Alemania, el reglamento oficial de honorarios de arquitectos e ingenieros (HOAI) es una referencia habitual; desde 2021 sus tarifas son orientativas y no mínimos obligatorios. Interioristas y diseñadores de interiores suelen cobrar un importe fijo por proyecto o por estancia, por hora, por metro cuadrado o una combinación. Algunos añaden un margen sobre los muebles que compran por usted.</p>
<p>Elija el modelo que elija, pida el alcance por escrito: qué fases incluye, cuántas opciones de diseño, cuántas revisiones y si las visitas a obra y las compras forman parte.</p>
<h2>Ver el resultado antes de decidir</h2>
<p>Diseñe quien diseñe su proyecto, las decisiones son más fáciles cuando se pueden ver. La visualización 3D permite comparar distribuciones, materiales e iluminación antes de pedir o construir nada, tanto en una sola habitación como en todo un edificio. Nuestra <a href="/es/blog/render-de-interiores-guia">guía de render de interiores</a> explica cómo funciona ese proceso y cómo encargarlo, y <a href="/es/blog/visualizacion-3d-diseno-de-interiores">visualización 3D en diseño de interiores</a> muestra qué decisiones facilita.</p>
<h2>Cuando un estudio cubre varios papeles</h2>
<p>Contratar empresas distintas para el edificio, los interiores y las imágenes supone tres traspasos. Algunos estudios combinan diseño y visualización, de modo que el mismo equipo desarrolla un concepto y lo muestra. En VARI trabajamos en diseño arquitectónico, interiorismo y visualización 3D, del dibujo 2D y el BIM a los renders y los tours virtuales. Puede ver ejemplos en <a href="/es/work">nuestros proyectos</a>, como el salón abovedado de <a href="/es/work/hearthstone-haven">Hearthstone Haven</a>, o leer sobre nuestros <a href="/es/services">servicios</a>.</p>
<p>¿No está seguro de qué necesita su proyecto? <a href="/es/contact">Descríbanoslo</a> y se lo diremos con honestidad, también cuando necesite un arquitecto colegiado en su país.</p>
<h3>Fuentes</h3>
<ul><li>Bundesarchitektenkammer (Cámara Federal de Arquitectos de Alemania), sobre títulos protegidos: <a href="https://bak.de">bak.de</a></li><li>Architects Registration Board (Reino Unido): <a href="https://arb.org">arb.org</a>.uk</li><li>HOAI, Honorarordnung für Architekten und Ingenieure (versión de 2021): <a href="https://gesetze-im-internet.de/hoai_2013">gesetze-im-internet.de/hoai_2013</a></li></ul>$v$, $v$["Los arquitectos diseñan edificios y responden de la estructura, la seguridad y las licencias.", "Los interioristas con formación técnica intervienen en la construcción interior; los diseñadores de interiores definen distribución, acabados y ambiente.", "Lo que cambia su proyecto decide a quién necesita: obra nueva, cambio estructural, acondicionamiento o renovación.", "Los títulos profesionales se protegen de forma distinta según el país; consulte las normas locales."]$v$::jsonb, $v$Arquitecto, interiorista o diseñador de interiores$v$, $v$Arquitecto, interiorista o diseñador de interiores: quién hace qué, dónde están los límites legales, cómo se cobran los honorarios y a quién necesita su proyecto.$v$, $v$arquitecto interiorista o diseñador de interiores$v$, true, 831),
  (pid, $v$tr$v$, $v$mimar-ic-mimar-ic-tasarimci-farki$v$, $v$Mimar, İç Mimar ve İç Tasarımcı Farkı: Kime İhtiyacınız Var?$v$, $v$Kim ne yapar, yasal sınırlar nerede, ücretler genellikle nasıl işler ve projeniz hangi profesyonele ihtiyaç duyar: ev sahipleri ve işletmeler için açık bir rehber.$v$, $v$<p>Mimar, iç mimar ve iç tasarımcı farkı, onlarla düzenli çalışanlar dahil neredeyse herkesin kafasını karıştıracak kadar iç içe geçer. Kısaca: <strong>Mimar</strong> binaları tasarlar ve taşıyıcı sistemden, güvenlikten ve izinlerden sorumludur. <strong>İç tasarımcı</strong> mekânların içini şekillendirir: yerleşim, kaplamalar, mobilya, ışık ve atmosfer. <strong>İç mimar</strong> ikisinin arasında durur; duvarların yerini değiştirmek, yeni merdivenler ve tesisat gibi yapıya daha derin uzanan iç mekân işleri yapar.</p>
<p>Kime ihtiyacınız olduğu tek bir soruya bağlıdır: <strong>Projeniz neyi değiştirecek?</strong></p>
<h2>Neyin değiştiğinden başlayın</h2>
<p><strong>Yeni bir bina ya da ek bina.</strong> Bir mimara ihtiyacınız var. Yeni yapılar yönetmeliklere uygun bir tasarım, statik koordinasyon ve çoğu yerde yetkili bir profesyonelin imzaladığı bir ruhsat başvurusu gerektirir.</p>
<p><strong>Mevcut bir binada taşıyıcı değişiklikler.</strong> Taşıyıcı bir duvarı kaldırmak, asma kat eklemek, merdiveni değiştirmek ya da tesisatı yeniden yönlendirmek; bir mimar ya da iç mimarın yanı sıra bir inşaat mühendisi gerektirir. Pek çok yerde bu tür işler için izin gerekir.</p>
<p><strong>Bitmiş bir yapı içinde iç düzenleme.</strong> Tamamlanmış bir binanın içinde yapılacak yeni bir daire ya da ofis, iç mimarların ve iç tasarımcıların doğal alanıdır: yerleşim, mutfaklar, banyolar, sabit mobilyalar, aydınlatma ve kaplamalar.</p>
<p><strong>Yenileme.</strong> Taşıyıcı sisteme dokunmadan yeni kaplamalar, mobilya, renk ve aydınlatma. Genellikle doğru seçim bir iç tasarımcıdır.</p>
<p>Pek çok proje bunlardan birden fazlasını gerektirir. Bir villa bina için bir mimara, odalar için bir iç tasarımcıya ihtiyaç duyar; ikisi erken konuştuğunda sonuç daha iyi olur.</p>
<figure data-figure="" data-size="normal"><img src="https://static.wixstatic.com/media/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png/v1/fit/w_1800,h_3600,q_82,enc_avif,quality_auto/b80319_eaf114bae9ad46aebe7b9c11a9e978c2~mv2.png" alt="Timeless English Roof Architecture: VARI Studio mimari görselleştirmesi" loading="lazy"></figure>
<h2>Mimar, iç mimar ve iç tasarımcı farkı: her biri gerçekte ne yapar</h2>
<p><strong>Mimarlar</strong> bir projeyi brif ve arsadan konsept, tasarım geliştirme ve teknik çizimlere, oradan izinlere ve çoğu zaman şantiye denetimine kadar götürür. Mühendisleri koordine eder ve yönetmeliklere uyumdan sorumludur.</p>
<p><strong>İç mimarlar</strong> iç mekânları yapılı çevre olarak tasarlar: mekân planlaması, bölme duvarlar, tavanlar, merdivenler, aydınlatma ve tesisat koordinasyonu; uygulayıcıların üzerinden inşa ettiği teknik çizimlerle.</p>
<p><strong>İç tasarımcılar</strong> bir mekânın içindeki insanlar için nasıl göründüğüne, hissettirdiğine ve işlediğine odaklanır: yerleşim, malzemeler, renk, mobilya, tekstil, aydınlatma ve stil. Pek çoğu satın alma ve montajı da yönetir.</p>
<h2>Yasal sınırlar ülkeden ülkeye değişir</h2>
<p>Meslek unvanları dünyanın farklı yerlerinde farklı düzenlenir; projenizin bulunduğu yerdeki kuralları kontrol edin:</p>
<ul><li><strong>Almanya.</strong> "Architekt" ve "Innenarchitekt", eyaletlerin mimarlar yasalarıyla korunan meslek unvanlarıdır. Yalnızca bir eyalet mimarlar odasına (Architektenkammer) kayıtlı kişiler kullanabilir.</li><li><strong>Birleşik Krallık.</strong> "Architect" unvanı yasayla korunur. Yalnızca Architects Registration Board'a kayıtlı kişiler kullanabilir.</li><li><strong>ABD.</strong> Mimarlara her eyalet ayrı lisans verir. İç tasarım düzenlemesi büyük farklılık gösterir: Bazı eyaletler unvanı ya da mesleği düzenler, çoğu düzenlemez.</li></ul>
<p>Başka yerlerde, planladığınız işi kimin tasarlayıp imzalayabileceğini yerel meslek odasına ya da yapı ruhsatı veren kuruma sorun.</p>
<h2>Ücretler genellikle nasıl belirlenir</h2>
<p>Mimarlar çoğu zaman inşaat maliyetinin bir yüzdesini, aşama başına sabit bir ücreti ya da saatlik ücret teklif eder. Almanya'da mimar ve mühendislerin resmî ücret yönetmeliği (HOAI) yaygın bir referanstır. 2021'den beri oranları bağlayıcı alt sınırlar değil, yol gösterici değerlerdir. İç mimarlar ve iç tasarımcılar genellikle proje ya da oda başına sabit ücret, saatlik ücret, metrekare başına ücret ya da bunların bir birleşimini alır. Bazıları sizin için satın aldıkları mobilyalara bir kâr payı ekler.</p>
<p>Hangi modeli seçerseniz seçin, kapsamı yazılı isteyin: Hangi aşamalar dahil, kaç tasarım seçeneği, kaç revizyon ve şantiye ziyaretleri ile satın alma kapsamda mı?</p>
<h2>Karar vermeden önce sonucu görmek</h2>
<p>Projenizi kim tasarlarsa tasarlasın, kararlar görüldüğünde kolaylaşır. 3D görselleştirme, hiçbir şey sipariş edilmeden ya da yapılmadan yerleşimleri, malzemeleri ve aydınlatmayı karşılaştırmanızı sağlar; tek bir oda için de bütün bir bina için de. <a href="/tr/blog/ic-mekan-render-rehberi">İç mekân render rehberimiz</a> bu sürecin nasıl işlediğini ve nasıl brif verileceğini, <a href="/tr/blog/3d-gorsellestirme-ic-mimari">iç mimaride 3D görselleştirme</a> yazımız ise hangi kararları kolaylaştırdığını anlatıyor.</p>
<h2>Bir stüdyo birkaç rolü üstlenebildiğinde</h2>
<p>Bina, iç mekânlar ve görseller için ayrı firmalarla çalışmak üç ayrı devir teslim demektir. Bazı stüdyolar tasarımı ve görselleştirmeyi birleştirir; böylece aynı ekip bir konsept geliştirir ve onu gösterir. VARI'de mimari tasarım, iç mimari ve 3D görselleştirme alanlarında, 2D çizim ve BIM'den render ve sanal turlara kadar çalışıyoruz. Örnekleri <a href="/tr/work">projelerimizde</a>, örneğin <a href="/tr/work/hearthstone-haven">Hearthstone Haven</a> projesinin tonozlu oturma odasında görebilir ya da <a href="/tr/services">hizmetlerimiz</a> hakkında okuyabilirsiniz.</p>
<p>Projenizin neye ihtiyaç duyduğundan emin değil misiniz? <a href="/tr/contact">Bize anlatın</a>; yerel olarak kayıtlı bir mimara ihtiyacınız olduğunda bile size dürüstçe söyleriz.</p>
<h3>Kaynaklar</h3>
<ul><li>Bundesarchitektenkammer (Almanya Federal Mimarlar Odası), korunan unvanlar hakkında: <a href="https://bak.de">bak.de</a></li><li>Architects Registration Board (Birleşik Krallık): <a href="https://arb.org">arb.org</a>.uk</li><li>HOAI, Honorarordnung für Architekten und Ingenieure (2021 sürümü): <a href="https://gesetze-im-internet.de/hoai_2013">gesetze-im-internet.de/hoai_2013</a></li></ul>$v$, $v$["Mimarlar binaları tasarlar ve taşıyıcı sistem, güvenlik ve izinlerden sorumludur.", "İç mimarlar yapıya da uzanan iç mekân işleri yapar; iç tasarımcılar yerleşimi, kaplamaları ve atmosferi şekillendirir.", "Projenizin neyi değiştireceği kime ihtiyacınız olduğunu belirler: yeni bina, taşıyıcı değişiklik, iç düzenleme ya da yenileme.", "Meslek unvanları ülkeye göre farklı korunur; yerel kuralları kontrol edin."]$v$::jsonb, $v$Mimar, İç Mimar ve İç Tasarımcı Farkı: Kime İhtiyacınız Var?$v$, $v$Mimar, iç mimar ve iç tasarımcı farkı: kim ne yapar, yasal sınırlar nerede, ücretler nasıl belirlenir ve projeniz hangisine ihtiyaç duyar.$v$, $v$mimar iç mimar iç tasarımcı farkı$v$, true, 677)
  on conflict (post_id, locale) do update set
    slug = excluded.slug, title = excluded.title, excerpt = excluded.excerpt, html = excluded.html, content = null,
    takeaways = excluded.takeaways, seo_title = excluded.seo_title, seo_description = excluded.seo_description,
